create table "public"."review_platforms" (
  "id" bigint generated by default as identity not null,
  "logo" character varying,
  "platform_name" character varying,
  "slug" character varying
);
alter table "public"."review_platforms" enable row level security;
CREATE UNIQUE INDEX review_platforms_pkey ON public.review_platforms USING btree (id);
alter table "public"."review_platforms"
add constraint "review_platforms_pkey" PRIMARY KEY using index "review_platforms_pkey";
grant delete on table "public"."review_platforms" to "anon";
grant insert on table "public"."review_platforms" to "anon";
grant references on table "public"."review_platforms" to "anon";
grant select on table "public"."review_platforms" to "anon";
grant trigger on table "public"."review_platforms" to "anon";
grant truncate on table "public"."review_platforms" to "anon";
grant update on table "public"."review_platforms" to "anon";
grant delete on table "public"."review_platforms" to "authenticated";
grant insert on table "public"."review_platforms" to "authenticated";
grant references on table "public"."review_platforms" to "authenticated";
grant select on table "public"."review_platforms" to "authenticated";
grant trigger on table "public"."review_platforms" to "authenticated";
grant truncate on table "public"."review_platforms" to "authenticated";
grant update on table "public"."review_platforms" to "authenticated";
grant delete on table "public"."review_platforms" to "service_role";
grant insert on table "public"."review_platforms" to "service_role";
grant references on table "public"."review_platforms" to "service_role";
grant select on table "public"."review_platforms" to "service_role";
grant trigger on table "public"."review_platforms" to "service_role";
grant truncate on table "public"."review_platforms" to "service_role";
grant update on table "public"."review_platforms" to "service_role";
create policy "Allow authenticated to add (insert) review_platform" on "public"."review_platforms" as permissive for
insert to authenticated,
  supabase_auth_admin with check (true);
create policy "Allow authenticated to delete review_platform" on "public"."review_platforms" as permissive for delete to authenticated using (true);
create policy "Allow authenticated to read (select) review platforms" on "public"."review_platforms" as permissive for
select to public using (true);
create policy "Allow authenticated to update review_platform" on "public"."review_platforms" as permissive for
update to authenticated using (true) with check (true);
